s = s.rstrip() + """

/// Returns whether a by-reference parameter's type is WIDER than the caller's current one.
///
/// Direction matters: a callee compiled for `array<int>` must never narrow a caller holding
/// `array<mixed>`, because it cannot unbox storage it does not own. Only the two widenings a
/// body can actually perform count — an element representation that became `Mixed`, and an
/// empty `array<never>` that gained one.
fn by_ref_arg_type_widens(current: &PhpType, param_ty: &PhpType) -> bool {
    match (current.codegen_repr(), param_ty.codegen_repr()) {
        (PhpType::Array(current_elem), PhpType::Array(param_elem)) => {
            element_widens(&current_elem, &param_elem)
        }
        (
            PhpType::AssocArray {
                value: current_value,
                ..
            },
            PhpType::AssocArray {
                value: param_value, ..
            },
        ) => element_widens(&current_value, &param_value),
        _ => false,
    }
}

/// Returns whether one array element representation is wider than another.
fn element_widens(current: &PhpType, param: &PhpType) -> bool {
    let current = current.codegen_repr();
    let param = param.codegen_repr();
    if current == param {
        return false;
    }
    current == PhpType::Never || param == PhpType::Mixed
}
"""
open(p,'w').write(s)
print('directional predicate added')
